ERP_PDP_V2_B64_7

    ROUTE_BLOCK_FILE="$(mktemp "${TMPDIR:-/tmp}/linxen_pdp_erp_route.XXXXXX")"

    cat > "$ROUTE_BLOCK_FILE" <<'ROUTE_BLOCK'
/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_START */
Route::prefix('commerce/v2/sites/{site}/catalog')
    ->middleware([
        \App\Http\Middleware\Commerce\CommerceApiExceptionBoundary::class,
        \App\Http\Middleware\Commerce\ResolveCommerceSiteContext::class,
        \App\Http\Middleware\Commerce\RequireCommerceCatalogRead::class,
    ])
    ->group(function () {
        Route::post('/products/{product}/size-advice', [
            \App\Http\Controllers\Api\Commerce\V2\CatalogProductSizeAdviceController::class,
            '__invoke',
        ])->where('site', '[A-Za-z0-9.-]+')
            ->where('product', '[A-Za-z0-9._-]+')
            ->middleware('throttle:60,1');
    });
/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_END */
ROUTE_BLOCK

    export LINXEN_ERP_ROUTES='routes/api.php'
    export LINXEN_ERP_PDP_ROUTE_BLOCK="$ROUTE_BLOCK_FILE"

    php <<'PHP'
<?php

$path = getenv('LINXEN_ERP_ROUTES');
$blockPath = getenv('LINXEN_ERP_PDP_ROUTE_BLOCK');
$source = file_get_contents($path);
$block = file_get_contents($blockPath);

if (! is_string($source) || ! is_string($block)) {
    fwrite(STDERR, "ERROR: Không đọc được ERP route source/block.\n");
    exit(1);
}

$start = '/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_START */';
$end = '/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_END */';
$startCount = substr_count($source, $start);
$endCount = substr_count($source, $end);

if ($startCount !== $endCount || $startCount > 1) {
    fwrite(STDERR, "ERROR: ERP PDP route marker imbalance.\n");
    exit(1);
}

if ($startCount === 1) {
    $pattern = '/'
        . preg_quote($start, '/')
        . '.*?'
        . preg_quote($end, '/')
        . '/s';
    $source = preg_replace($pattern, '', $source, 1, $count);

    if (! is_string($source) || $count !== 1) {
        fwrite(STDERR, "ERROR: Không xóa được ERP PDP route block cũ.\n");
        exit(1);
    }
}

$patched = rtrim($source)
    . "\n\n"
    . trim($block)
    . "\n";

$written = file_put_contents($path, $patched);

if ($written === false || $written !== strlen($patched)) {
    fwrite(STDERR, "ERROR: Không ghi đầy đủ routes/api.php.\n");
    exit(1);
}
PHP

    rm -f "$ROUTE_BLOCK_FILE"

    for FILE in \
      'app/Services/Commerce/CommerceCatalogProjectionService.php' \
      'app/Services/Commerce/CommercePdpSettingsService.php' \
      'app/Services/Commerce/CommercePdpExperienceService.php' \
      'app/Services/Commerce/CommercePdpSizeAdvisorService.php' \
      'app/Http/Controllers/Api/Commerce/V2/CatalogProductSizeAdviceController.php' \
      'app/Console/Commands/Commerce/BootstrapPdpSalesExperienceCommand.php' \
      'app/Console/Commands/Commerce/AuditPdpSalesExperienceCommand.php'
    do
        php -l "$FILE"
    done

    php -l routes/api.php

    grep -Fq -- \
      "public const VERSION = 'commerce_catalog_projection_v2_1';" \
      app/Services/Commerce/CommerceCatalogProjectionService.php

    grep -Fq -- \
      "'pdp' => data_get(" \
      app/Services/Commerce/CommerceCatalogProjectionService.php

    grep -Fq -- \
      "'SALES_INBOX_SUPPORT_SINGLE'" \
      app/Services/Commerce/CommercePdpSettingsService.php

    grep -Fq -- \
      "'never_cross_color_fallback' => true" \
      app/Services/Commerce/CommercePdpExperienceService.php

    grep -Fq -- \
      "'needs_body_measurements'" \
      app/Services/Commerce/CommercePdpSizeAdvisorService.php

    grep -Fq -- \
      'AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_START' \
      routes/api.php

    artisan_safe optimize:clear

    set +e
    COMMANDS="$(artisan_safe list --raw 2>/dev/null)"
    COMMAND_STATUS=$?
    set -e

    if [ "$COMMAND_STATUS" -eq 0 ] \
        && printf '%s\n' "$COMMANDS" \
          | grep -Eq \
            '^commerce:(bootstrap-pdp-sales-experience|audit-pdp-sales-experience)([[:space:]]|$)'
    then
        printf '%s\n' 'ERP_PDP_COMMAND_DISCOVERY=PASS'
    else
        printf '%s\n' \
          'ERP_PDP_COMMAND_DISCOVERY=WARNING_CHECK_ON_PRODUCTION'
    fi

    trap - ERR

    printf '%s\n' 'LINXEN_PDP_SALES_EXPERIENCE_ERP_SOURCE_PATCH=PASS'
    printf '%s\n' 'MEDIA_PRIORITY=SALES_INBOX_THEN_PRODUCT_CLARITY'
    printf '%s\n' 'MEDIA_LIMIT_PER_COLOR=6'
    printf '%s\n' 'CROSS_COLOR_MEDIA_FALLBACK=BLOCKED'
    printf '%s\n' 'SIZE_ADVISOR=PROVISIONAL_BODY_MEASUREMENTS'
    printf '%s\n' 'HEIGHT_WEIGHT_ONLY_RECOMMENDATION=BLOCKED'
    printf '%s\n' 'MIGRATION=NONE'
    printf '%s\n' 'PATCH_DB_MUTATION=NONE'
    printf '%s\n' 'PATCH_PROVIDER_CALL=NONE'
    printf '%s\n' 'CHECKOUT_ORDER_KIOTVIET_META=UNCHANGED'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi

if [ "$TARGET" = 'storefront' ]; then
    REQUIRED=(
        'app/Services/CommerceV2/CommerceV2Presenter.php'
        'app/Services/CommerceV2/ErpCommerceClient.php'
        'app/Exceptions/CommerceV2/CommerceV2ClientException.php'
        'app/Http/Controllers/CommerceV2/CatalogPageController.php'
        'app/Services/CommerceV2/SessionCartService.php'
        'resources/views/commerce_v2/pages/product.blade.php'
        'resources/views/commerce_v2/layouts/app.blade.php'
        'routes/commerce_v2.php'
        'public/commerce-v2/commerce.css'
        'public/commerce-v2/commerce.js'
    )

    for FILE in "${REQUIRED[@]}"; do
        test -f "$FILE" || {
            printf 'ERROR: Missing Storefront dependency: %s\n' \
              "$FILE" >&2
            exit 1
        }
    done

    grep -Fq -- \
      "->name('product')" \
      routes/commerce_v2.php

    grep -Fq -- \
      'id="lxv2ProductData"' \
      resources/views/commerce_v2/pages/product.blade.php

