SF_PDP_V2_B64_7

    export LINXEN_STOREFRONT_ROUTES='routes/commerce_v2.php'

    php <<'PHP'
<?php

$path = getenv('LINXEN_STOREFRONT_ROUTES');
$source = file_get_contents($path);

if (! is_string($source)) {
    fwrite(STDERR, "ERROR: Không đọc được Storefront routes.\n");
    exit(1);
}

$import = 'use App\\Http\\Controllers\\CommerceV2\\PdpSizeAdviceController;';
$importAnchor = 'use App\\Http\\Controllers\\CommerceV2\\OrderController;';

if (! str_contains($source, $import)) {
    if (! str_contains($source, $importAnchor)) {
        fwrite(STDERR, "ERROR: Thiếu Storefront route import anchor.\n");
        exit(1);
    }

    $source = str_replace(
        $importAnchor,
        $importAnchor . "\n" . $import,
        $source,
        $count
    );

    if ($count !== 1) {
        fwrite(STDERR, "ERROR: Storefront import replacement count invalid.\n");
        exit(1);
    }
}

$start = '/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_START */';
$end = '/* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_END */';
$startCount = substr_count($source, $start);
$endCount = substr_count($source, $end);

if ($startCount !== $endCount || $startCount > 1) {
    fwrite(STDERR, "ERROR: Storefront PDP route marker imbalance.\n");
    exit(1);
}

if ($startCount === 1) {
    $pattern = '/'
        . preg_quote($start, '/')
        . '.*?'
        . preg_quote($end, '/')
        . '/s';
    $source = preg_replace($pattern, '', $source, 1, $count);

    if (! is_string($source) || $count !== 1) {
        fwrite(STDERR, "ERROR: Không xóa được Storefront PDP route block cũ.\n");
        exit(1);
    }
}

$productAnchor = <<<'ANCHOR'
        Route::get('/p/{slug}', [
            CatalogPageController::class,
            'product',
        ])->where('slug', '[A-Za-z0-9._-]+')
            ->name('product');
ANCHOR;

if (substr_count($source, $productAnchor) !== 1) {
    fwrite(STDERR, "ERROR: Không tìm thấy canonical Storefront product route.\n");
    exit(1);
}

$routeBlock = <<<'ROUTE'
        /* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_START */
        Route::post('/p/{slug}/size-advice', [
            PdpSizeAdviceController::class,
            '__invoke',
        ])->where('slug', '[A-Za-z0-9._-]+')
            ->middleware('throttle:30,1')
            ->name('product.size_advice');
        /* AI_PATCH_LINXEN_PDP_SALES_EXPERIENCE_V2_END */
ROUTE;

$source = str_replace(
    $productAnchor,
    $productAnchor . "\n\n" . rtrim($routeBlock),
    $source,
    $count
);

if ($count !== 1) {
    fwrite(STDERR, "ERROR: Storefront PDP route insertion failed.\n");
    exit(1);
}

$written = file_put_contents($path, $source);

if ($written === false || $written !== strlen($source)) {
    fwrite(STDERR, "ERROR: Không ghi đầy đủ Storefront routes.\n");
    exit(1);
}
PHP

    for FILE in \
      'app/Services/CommerceV2/CommerceV2Presenter.php' \
      'app/Services/CommerceV2/ErpCommerceClient.php' \
      'app/Http/Controllers/CommerceV2/PdpSizeAdviceController.php' \
      'app/Console/Commands/CommerceV2PdpSalesExperienceSmokeCommand.php'
    do
        php -l "$FILE"
    done

    php -l routes/commerce_v2.php

    grep -Fq -- \
      'data-lxpdp-gallery' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq -- \
      'data-lxpdp-size-advisor' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq -- \
      'data-lxpdp-mobile-buy' \
      resources/views/commerce_v2/pages/product.blade.php

    grep -Fq -- \
      'public function productSizeAdvice(' \
      app/Services/CommerceV2/ErpCommerceClient.php

    grep -Fq -- \
      "->name('product.size_advice')" \
      routes/commerce_v2.php

    grep -Fq -- \
      'escapeHtml' \
      public/commerce-v2/pdp-sales-experience.js

    grep -Fq -- \
      'mainImage.removeAttribute' \
      public/commerce-v2/pdp-sales-experience.js

    if command -v node >/dev/null 2>&1; then
        if node --check \
          public/commerce-v2/pdp-sales-experience.js
        then
            printf '%s\n' 'PDP_JS_SYNTAX=PASS'
        else
            printf '%s\n' \
              'PDP_JS_SYNTAX=WARNING_NODE_CHECK_FAILED'
        fi
    else
        printf '%s\n' \
          'PDP_JS_SYNTAX=WARNING_NODE_UNAVAILABLE'
    fi

    artisan_safe optimize:clear
    artisan_safe view:clear
    artisan_safe commerce-v2:pdp-sales-experience-smoke
    artisan_safe view:clear

    trap - ERR

    printf '%s\n' 'LINXEN_PDP_SALES_EXPERIENCE_STOREFRONT_SOURCE_PATCH=PASS'
    printf '%s\n' 'COLOR_AWARE_GALLERY=ENABLED'
    printf '%s\n' 'OUT_OF_STOCK_COLOR_BROWSING=ENABLED'
    printf '%s\n' 'CROSS_COLOR_MEDIA_FALLBACK=BLOCKED'
    printf '%s\n' 'STICKY_DESKTOP_PURCHASE_PANEL=ENABLED'
    printf '%s\n' 'STICKY_MOBILE_CTA=ENABLED'
    printf '%s\n' 'SIZE_ADVISOR_DRAWER=ENABLED'
    printf '%s\n' 'EXACT_SELLABLE_SKU_CART_CONTRACT=PRESERVED'
    printf '%s\n' 'MIGRATION=NONE'
    printf '%s\n' 'DB_MUTATION=NONE'
    printf '%s\n' 'ERP_API_CALL_DURING_LOCAL_PATCH=NONE'
    printf '%s\n' 'ORDER_PROVIDER_META_MUTATION=NONE'
    printf '%s\n' 'NPM_BUILD=NOT_REQUIRED'
    printf '%s\n' 'V1_STOREFRONT=UNCHANGED'
    printf 'BACKUP_DIR=%s\n' "$BACKUP_ROOT"

    exit 0
fi
